<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
if(getenv('ODONTOCARE_VALIDACAO_ISOLADA')!=='1'){fwrite(STDERR,"Exige ambiente isolado.\n");exit(2);}
foreach(['ODONTOCARE_API_URL','ODONTOCARE_DB_HOST','ODONTOCARE_DB_NAME','ODONTOCARE_DB_USER','ODONTOCARE_DB_PASS'] as $key){if(getenv($key)===false){fwrite(STDERR,"Configure $key.\n");exit(2);}}
$base=rtrim(getenv('ODONTOCARE_API_URL'),'/');$db=new PDO('mysql:host='.getenv('ODONTOCARE_DB_HOST').';dbname='.getenv('ODONTOCARE_DB_NAME').';charset=utf8mb4',getenv('ODONTOCARE_DB_USER'),getenv('ODONTOCARE_DB_PASS'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$results=[];
function note($name,$ok,$detail=null){global $results;$results[]=['test'=>$name,'passed'=>$ok,'detail'=>$detail];echo ($ok?'PASS ':'FAIL ').$name.PHP_EOL;}
function raw($method,$path,$body=null,$token=null,$otherBase=null){global $base;$h=curl_init(($otherBase??$base).'/'.$path);$headers=['Accept: application/json'];if($token)$headers[]='Authorization: Bearer '.$token;if($body!==null)$headers[]='Content-Type: application/json';curl_setopt_array($h,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_HTTPHEADER=>$headers]);if($body!==null)curl_setopt($h,CURLOPT_POSTFIELDS,json_encode($body));$text=curl_exec($h);$code=curl_getinfo($h,CURLINFO_HTTP_CODE);$type=curl_getinfo($h,CURLINFO_CONTENT_TYPE);curl_close($h);return ['code'=>$code,'json'=>is_string($text)?json_decode($text,true):null,'type'=>$type??'','raw'=>$text?:''];}
function wrapped($name,$response,$expected){$j=$response['json'];$valid=is_array($j)&&isset($j['success'],$j['message'],$j['errors'])&&array_key_exists('data',$j)&&is_bool($j['success'])&&is_string($j['message'])&&is_array($j['errors'])&&$j['success']===($expected<300)&&str_starts_with($response['type'],'application/json');note($name,$response['code']===$expected&&$valid,['expected'=>$expected,'actual'=>$response['code']]);return $j['data']??null;}
$password=bin2hex(random_bytes(16));$login='accept_'.bin2hex(random_bytes(5));$salt=random_bytes(16);$hash='pbkdf2-sha256$210000$'.base64_encode($salt).'$'.base64_encode(hash_pbkdf2('sha256',$password,$salt,210000,32,true));$db->prepare('INSERT INTO usuario(nome,login,senha,tipoUsuario) VALUES(?,?,?,?)')->execute(['Aceite administrador',$login,$hash,'Administrador']);
$auth=raw('POST','api/auth/login',['identificador'=>$login,'senha'=>$password]);$admin=wrapped('Login administrador com envelope 200',$auth,200)['token'];
wrapped('Sem token: envelope 401',raw('GET','api/pacientes'),401);
wrapped('Campos ausentes: envelope 400',raw('POST','api/auth/login',[]),400);
wrapped('Recurso inexistente: envelope 404',raw('GET','api/pacientes/2147483647',null,$admin),404);
wrapped('Metodo inadequado: envelope 405',raw('PATCH','api/pacientes',null,$admin),405);
wrapped('Rota inexistente: envelope 404',raw('GET','api/recurso-nao-existente',null,$admin),404);
$users=[];$hashes=[];foreach(['Secretária','Dentista'] as $index=>$role){$userLogin=$login.'_'.$index;$data=wrapped('Cadastro '.$role.' com envelope 201',raw('POST','api/auth/registro',['nome'=>'Aceite '.$role,'login'=>$userLogin,'senha'=>$password,'tipoUsuario'=>$role],$admin),201);$users[$role]=['id'=>$data['idUsuario'],'login'=>$userLogin];$q=$db->prepare('SELECT senha FROM usuario WHERE idUsuario=?');$q->execute([$data['idUsuario']]);$stored=$q->fetchColumn();$hashes[]=$stored;note('Senha '.$role.' protegida no banco',is_string($stored)&&str_starts_with($stored,'pbkdf2-sha256$210000$')&&$stored!==$password);}
note('Mesmo segredo gera hashes distintos por salt',count(array_unique($hashes))===2);
wrapped('Login duplicado: envelope 409',raw('POST','api/auth/registro',['nome'=>'Duplicado','login'=>$users['Dentista']['login'],'senha'=>$password,'tipoUsuario'=>'Dentista'],$admin),409);
$auth=raw('POST','api/auth/login',['identificador'=>$users['Secretária']['login'],'senha'=>$password]);$secretary=wrapped('Login Secretaria com envelope 200',$auth,200)['token'];
$list=wrapped('Secretaria consulta profissionais',raw('GET','api/usuarios',null,$secretary),200);note('Listagem nao divulga senha',is_array($list)&&count(array_filter($list,fn($u)=>array_key_exists('senha',$u)))===0);
wrapped('Secretaria nao cadastra contas: envelope 403',raw('POST','api/auth/registro',['nome'=>'Bloqueado','login'=>'blocked_'.bin2hex(random_bytes(4)),'senha'=>$password,'tipoUsuario'=>'Administrador'],$secretary),403);
$patient=wrapped('Secretaria cadastra paciente',raw('POST','api/pacientes',['nome'=>'Paciente sintetico aceite','cpf'=>substr((string)hrtime(true),-11)],$secretary),201);
wrapped('Secretaria altera paciente',raw('PUT','api/pacientes/'.$patient['idPaciente'],['nome'=>'Paciente atualizado aceite'],$secretary),200);
$auth=raw('POST','api/auth/login',['identificador'=>$users['Dentista']['login'],'senha'=>$password]);$dentist=wrapped('Login Dentista com envelope 200',$auth,200)['token'];
wrapped('Dentista le pacientes',raw('GET','api/pacientes',null,$dentist),200);
wrapped('Dentista nao altera paciente: envelope 403',raw('PUT','api/pacientes/'.$patient['idPaciente'],['nome'=>'Proibido'],$dentist),403);
wrapped('Senha incorreta: envelope 401',raw('POST','api/auth/login',['identificador'=>$login,'senha'=>'Senha incorreta']),401);
if(getenv('ODONTOCARE_API_FALHA_URL')){$r=raw('POST','api/auth/login',['identificador'=>'teste indisponibilidade','senha'=>$password],null,rtrim(getenv('ODONTOCARE_API_FALHA_URL'),'/'));wrapped('Falha de banco: envelope 500',$r,500);note('Erro 500 nao divulga stack ou conexao',!preg_match('/SQLSTATE|StackTrace|MySqlException|Password=|ConnectionString| at OdontoCare/',$r['raw'])&&str_contains($r['json']['message']??'','erro interno'));}
$out=['database'=>$db->query('SELECT VERSION()')->fetchColumn(),'results'=>$results];if(getenv('ODONTOCARE_VALIDACAO_RESULTADO'))file_put_contents(getenv('ODONTOCARE_VALIDACAO_RESULTADO'),json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));exit(count(array_filter($results,fn($r)=>!$r['passed']))?1:0);
